1	// Helper de redimensionamento + recompressão de imagem.
2	//
3	// PORQUÊ: fotos de câmera mobile e páginas de PDF chegam em altíssima resolução
4	// e, quando convertidas direto em base64, mantêm várias cópias enormes vivas em
5	// memória ao mesmo tempo (data URL crua + base64 + payload da edge function).
6	// Em abas mobile isso estoura o navegador antes mesmo de chamar o OCR. Reduzir o
7	// lado maior para 2000px e recomprimir em JPEG 0.85 corta o pico de memória em
8	// ~1 ordem de grandeza sem perda relevante de leitura do OCR.
9	
10	/** Lado maior máximo (px) aprovado para conversões de imagem do OCR de NF. */
11	export const NF_IMAGE_MAX_DIM = 2000;
12	
13	/** Qualidade JPEG aprovada para conversões de imagem do OCR de NF. */
14	export const NF_IMAGE_JPEG_QUALITY = 0.85;
15	
16	/** Remove o prefixo `data:image/...;base64,` retornando só o payload base64. */
17	export function stripDataUrlPrefix(dataUrl: string): string {
18	  const commaIdx = dataUrl.indexOf(',');
19	  return commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl;
20	}
21	
22	/**
23	 * Calcula a escala de downscale mantendo proporção.
24	 * PORQUÊ: nunca fazer upscale — se a imagem já é menor que maxDim, escala = 1
25	 * para não inflar memória/peso sem ganho de leitura.
26	 */
27	function computeScale(width: number, height: number, maxDim: number): number {
28	  const largest = Math.max(width, height);
29	  return largest > maxDim ? maxDim / largest : 1;
30	}
31	
32	interface Dimensions {
33	  width: number;
34	  height: number;
35	}
36	
37	/**
38	 * Desenha a fonte (ImageBitmap ou HTMLImageElement) num canvas com lado maior
39	 * limitado a maxDim e exporta JPEG. Libera o canvas no finally porque um canvas
40	 * grande não liberado é justamente uma das cópias que estouram a memória.
41	 */
42	function drawToJpegBase64(
43	  source: CanvasImageSource,
44	  dims: Dimensions,
45	  maxDim: number,
46	  quality: number,
47	): string {
48	  const scale = computeScale(dims.width, dims.height, maxDim);
49	  const canvas = document.createElement('canvas');
50	  try {
51	    canvas.width = Math.round(dims.width * scale);
52	    canvas.height = Math.round(dims.height * scale);
53	    const ctx = canvas.getContext('2d');
54	    if (!ctx) {
55	      throw new Error('Canvas 2D context indisponível');
56	    }
57	    ctx.drawImage(source, 0, 0, canvas.width, canvas.height);
58	    const dataUrl = canvas.toDataURL('image/jpeg', quality);
59	    return stripDataUrlPrefix(dataUrl);
60	  } finally {
61	    // Zera o canvas para que o backing store seja coletado imediatamente.
62	    canvas.width = 0;
63	    canvas.height = 0;
64	  }
65	}
66	
67	/** Caminho de fallback via HTMLImageElement quando createImageBitmap falha. */
68	function blobToBase64ViaImage(
69	  blob: Blob,
70	  maxDim: number,
71	  quality: number,
72	): Promise<string> {
73	  return new Promise<string>((resolve, reject) => {
74	    const url = URL.createObjectURL(blob);
75	    const img = new Image();
76	    img.onload = () => {
77	      try {
78	        const base64 = drawToJpegBase64(
79	          img,
80	          { width: img.naturalWidth, height: img.naturalHeight },
81	          maxDim,
82	          quality,
83	        );
84	        resolve(base64);
85	      } catch (err) {
86	        reject(err instanceof Error ? err : new Error(String(err)));
87	      } finally {
88	        // Libera o object URL para não vazar o blob original em memória.
89	        URL.revokeObjectURL(url);
90	      }
91	    };
92	    img.onerror = () => {
93	      URL.revokeObjectURL(url);
94	      reject(new Error('Falha ao carregar imagem para downscale'));
95	    };
96	    img.src = url;
97	  });
98	}
99	
100	/**
101	 * Converte um Blob/File de imagem para base64 JPEG já reduzido.
102	 * Usa createImageBitmap quando disponível (mais leve, sem manter HTMLImageElement
103	 * vivo) e cai para Image+ObjectURL como fallback. Em ambos os caminhos os
104	 * recursos intermediários são liberados — esse é o ponto central do fix de
105	 * memória.
106	 */
107	export async function blobToDownscaledBase64(
108	  blob: Blob,
109	  maxDim: number = NF_IMAGE_MAX_DIM,
110	  quality: number = NF_IMAGE_JPEG_QUALITY,
111	): Promise<string> {
112	  if (typeof createImageBitmap === 'function') {
113	    let bitmap: ImageBitmap | null = null;
114	    try {
115	      bitmap = await createImageBitmap(blob);
116	      return drawToJpegBase64(
117	        bitmap,
118	        { width: bitmap.width, height: bitmap.height },
119	        maxDim,
120	        quality,
121	      );
122	    } catch {
123	      // Fallback silencioso: alguns navegadores/jsdom não suportam o formato.
124	      return blobToBase64ViaImage(blob, maxDim, quality);
125	    } finally {
126	      // close() devolve a memória do bitmap imediatamente.
127	      bitmap?.close();
128	    }
129	  }
130	  return blobToBase64ViaImage(blob, maxDim, quality);
131	}
132	
133	/**
134	 * Lê um File de imagem e retorna SÓ o base64 JPEG já reduzido (sem prefixo
135	 * data URL). Assinatura principal usada pelo fluxo de OCR de NF.
136	 */
137	export async function fileToDownscaledBase64(
138	  file: File,
139	  maxDim: number = NF_IMAGE_MAX_DIM,
140	  quality: number = NF_IMAGE_JPEG_QUALITY,
141	): Promise<string> {
142	  return blobToDownscaledBase64(file, maxDim, quality);
143	}
144	
145	/**
146	 * Lê um File de imagem e devolve um NOVO File JPEG já reduzido.
147	 *
148	 * PORQUÊ: o fluxo de captura por câmera na PWA mobile precisa de um File pra
149	 * trafegar pelos states (selectedFile/selectedFiles), upload pro Supabase
150	 * Storage e persistência durável (localStorage). Antes a captura mantinha o
151	 * File full-res em memória e ainda gerava um data URL gigante via
152	 * FileReader.readAsDataURL antes de reduzir — esse pico era a causa do OOM
153	 * que matava o WebView no Android. Aqui vamos direto do Blob ao File reduzido,
154	 * sem nenhum intermediário em resolução cheia.
155	 *
156	 * Saída sempre `image/jpeg` (forçamos a extensão `.jpg` no nome) porque o
157	 * downscale recomprime em JPEG.
158	 */
159	export async function fileToDownscaledFile(
160	  file: File,
161	  name?: string,
162	  maxDim: number = NF_IMAGE_MAX_DIM,
163	  quality: number = NF_IMAGE_JPEG_QUALITY,
164	): Promise<File> {
165	  const base64 = await blobToDownscaledBase64(file, maxDim, quality);
166	  // Decodifica o base64 já reduzido para bytes — peak de memória aqui é só o
167	  // tamanho do JPEG comprimido (~centenas de KB), não a foto crua.
168	  const binary = atob(base64);
169	  const bytes = new Uint8Array(binary.length);
170	  for (let i = 0; i < binary.length; i++) {
171	    bytes[i] = binary.charCodeAt(i);
172	  }
173	  const baseName = (name ?? file.name).replace(/\.[^.]+$/, '');
174	  const outName = `${baseName || 'foto'}.jpg`;
175	  return new File([bytes], outName, {
176	    type: 'image/jpeg',
177	    lastModified: Date.now(),
178	  });
179	}
180	
181	/** Converte uma data URL em Blob sem manter a string crua além do necessário. */
182	function dataUrlToBlob(dataUrl: string): Blob {
183	  const [header, payload] = dataUrl.split(',');
184	  const mime = header.match(/:(.*?);/)?.[1] ?? 'image/jpeg';
185	  const binary = atob(payload);
186	  const bytes = new Uint8Array(binary.length);
187	  for (let i = 0; i < binary.length; i++) {
188	    bytes[i] = binary.charCodeAt(i);
189	  }
190	  return new Blob([bytes], { type: mime });
191	}
192	
193	/**
194	 * Reduz uma data URL completa e retorna uma data URL JPEG reduzida (com prefixo).
195	 * PORQUÊ: usada antes de gravar a foto no sessionStorage — gravar a foto crua
196	 * full-res estoura a cota e a memória; o que persiste deve ser a versão leve.
197	 */
198	export async function dataUrlToDownscaledDataUrl(
199	  dataUrl: string,
200	  maxDim: number = NF_IMAGE_MAX_DIM,
201	  quality: number = NF_IMAGE_JPEG_QUALITY,
202	): Promise<string> {
203	  const blob = dataUrlToBlob(dataUrl);
204	  const base64 = await blobToDownscaledBase64(blob, maxDim, quality);
205	  return `data:image/jpeg;base64,${base64}`;
206	}
