1	import { useState, useRef, DragEvent, ChangeEvent, useEffect } from "react";
2	import { Upload, FileText, CheckCircle, Camera, Plus, X } from "lucide-react";
3	import { Input } from "@/shared/ui/input";
4	import { Button } from "@/shared/ui/button";
5	import { cn } from "@/shared/lib/utils";
6	import { useIsMobile } from "@/shared/hooks/use-mobile";
7	import { useHasCamera } from "@/shared/hooks/use-mobile";
8	import { toast } from "sonner";
9	import { wideError } from '@/shared/lib/telemetry/wide-events';
10	import { fileToDownscaledFile } from "@/features/notas-fiscais/lib/downscaleImage";
11	import {
12	  savePendingCapture,
13	  setPendingCaptureFlag,
14	  clearPendingCaptureFlag,
15	} from "@/features/notas-fiscais/lib/pendingCapture";
16	
17	interface DragDropUploadAreaProps {
18	  onFileSelect: (file: File) => void;
19	  selectedFile: File | null;
20	  onFilesSelect?: (files: File[]) => void;
21	  selectedFiles?: File[];
22	  multiple?: boolean;
23	  accept?: string;
24	  disabled?: boolean;
25	}
26	
27	/**
28	 * Garante que imagens sejam reduzidas (≤2000px, JPEG 0.85) antes de entrar no
29	 * state da página. PDFs passam intactos — pdf.js cuida do downscale por página
30	 * no `processImage`/`pdfToImageBase64Pages`.
31	 *
32	 * PORQUÊ: a foto crua de câmera mobile (≈4000×3000, ~10MB de dataURL ao
33	 * decodificar) é o pico que matava o WebView Android. Reduzir na ORIGEM —
34	 * antes do File entrar em selectedFile/selectedFiles — limita o pico a
35	 * centenas de KB e elimina cópias gigantes em memória.
36	 */
37	async function downscaleIfImage(file: File): Promise<File> {
38	  if (!file.type.startsWith('image/')) return file;
39	  try {
40	    return await fileToDownscaledFile(file);
41	  } catch (error) {
42	    wideError('dragDropUpload.downscaleImagem', 'Erro ao reduzir imagem; mantendo arquivo original como fallback', {
43	      attributes: {
44	        'error.message': String((error as Error)?.message || error),
45	        'operation.name': 'downscaleAtSource',
46	        'file.name': file.name,
47	        'file.type': file.type,
48	        'file.size': file.size,
49	      },
50	    });
51	    return file;
52	  }
53	}
54	
55	export const DragDropUploadArea = ({
56	  onFileSelect,
57	  selectedFile,
58	  onFilesSelect,
59	  selectedFiles = [],
60	  multiple = false,
61	  accept = 'image/*',
62	  disabled = false,
63	}: DragDropUploadAreaProps) => {
64	  const [isDragOver, setIsDragOver] = useState(false);
65	  const [isHovering, setIsHovering] = useState(false);
66	  const fileInputRef = useRef<HTMLInputElement>(null);
67	  const cameraInputRef = useRef<HTMLInputElement>(null);
68	  // Guarda anti-double-click; o flag durável (localStorage) é setado em paralelo
69	  // por setPendingCaptureFlag e serve ao hook de boot que redireciona pra NF.
70	  const isCapturing = useRef(false);
71	
72	  // Limpa o flag durável quando o usuário volta pro WebView (focus) — cobre o
73	  // caso de o usuário ter aberto a câmera e cancelado sem tirar foto. O flag
74	  // tem TTL próprio, isso é só a faxina best-effort no caminho feliz.
75	  useEffect(() => {
76	    const onFocus = () => {
77	      if (isCapturing.current) {
78	        // Pequeno delay: em alguns devices o onchange do input chega DEPOIS
79	        // do focus; se a foto vier, savePendingCapture cuida do flag.
80	        setTimeout(() => {
81	          if (isCapturing.current) {
82	            clearPendingCaptureFlag();
83	            isCapturing.current = false;
84	          }
85	        }, 1500);
86	      }
87	    };
88	    window.addEventListener('focus', onFocus);
89	    return () => window.removeEventListener('focus', onFocus);
90	  }, []);
91	
92	  const handleDragEnter = (e: DragEvent<HTMLDivElement>) => {
93	    e.preventDefault();
94	    e.stopPropagation();
95	    if (!disabled) {
96	      setIsDragOver(true);
97	    }
98	  };
99	
100	  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
101	    e.preventDefault();
102	    e.stopPropagation();
103	
104	    const rect = e.currentTarget.getBoundingClientRect();
105	    const x = e.clientX;
106	    const y = e.clientY;
107	
108	    if (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom) {
109	      setIsDragOver(false);
110	    }
111	  };
112	
113	  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
114	    e.preventDefault();
115	    e.stopPropagation();
116	  };
117	
118	  const handleDrop = async (e: DragEvent<HTMLDivElement>) => {
119	    e.preventDefault();
120	    e.stopPropagation();
121	    setIsDragOver(false);
122	
123	    if (disabled) return;
124	
125	    const files = Array.from(e.dataTransfer.files);
126	    if (files.length === 0) return;
127	    const validFiles = files.filter(f => {
128	      if (accept === 'image/*') return f.type.startsWith('image/');
129	      return accept.split(',').some(a => {
130	        const pat = '^' + a.trim().replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace('\\*', '.*') + '$';
131	        return new RegExp(pat).test(f.type);
132	      });
133	    });
134	    if (validFiles.length === 0) return;
135	
136	    // Downscale de imagens na entrada — vale tanto pro mobile (galeria) quanto
137	    // pra desktop (drag/drop): mantém o pipeline de memória previsível.
138	    const processed = await Promise.all(validFiles.map(downscaleIfImage));
139	
140	    if (multiple && onFilesSelect) {
141	      const merged = [...selectedFiles, ...processed].slice(0, 2);
142	      onFilesSelect(merged);
143	    } else {
144	      onFileSelect(processed[0]);
145	    }
146	  };
147	
148	  const handleFileInputChange = async (e: ChangeEvent<HTMLInputElement>) => {
149	    const files = e.target.files;
150	    if (!files || files.length === 0) {
151	      e.target.value = '';
152	      return;
153	    }
154	    const inputFiles = Array.from(files);
155	    const processed = await Promise.all(inputFiles.map(downscaleIfImage));
156	    if (multiple && onFilesSelect) {
157	      const merged = [...selectedFiles, ...processed].slice(0, 2);
158	      onFilesSelect(merged);
159	    } else {
160	      onFileSelect(processed[0]);
161	    }
162	    // Reset value para permitir re-seleção do mesmo arquivo
163	    e.target.value = '';
164	  };
165	
166	  const isMobile = useIsMobile();
167	  const { hasCamera, isChecking } = useHasCamera();
168	
169	  const handleClick = () => {
170	    if (disabled) return;
171	    if (isCapturing.current) return;
172	    // Se já tem 2 arquivos no multi-mode, não abrir seleção (limite atingido)
173	    if (multiple && selectedFiles.length >= 2) return;
174	    if (isMobile && hasCamera) {
175	      setPendingCaptureFlag();
176	      isCapturing.current = true;
177	      cameraInputRef.current?.click();
178	      return;
179	    }
180	    fileInputRef.current?.click();
181	  };
182	
183	  const handleCameraClick = (e: React.MouseEvent) => {
184	    e.stopPropagation();
185	    if (!disabled && hasCamera && !isCapturing.current) {
186	      setPendingCaptureFlag();
187	      isCapturing.current = true;
188	      cameraInputRef.current?.click();
189	    }
190	  };
191	
192	  const handleCameraCapture = async (e: ChangeEvent<HTMLInputElement>) => {
193	    const files = e.target.files;
194	    const raw = files && files.length > 0 ? files[0] : null;
195	    // Sempre limpa o flag — recebemos retorno do input (com ou sem foto).
196	    clearPendingCaptureFlag();
197	    isCapturing.current = false;
198	    if (!raw) {
199	      e.target.value = '';
200	      return;
201	    }
202	
203	    // PORQUÊ downscale ANTES de entregar via onFileSelect: o File cru de câmera
204	    // de Android costuma ter 5-10MB e segura um pico de ~13MB de dataURL ao
205	    // decodificar. Esse pico era o gatilho do OOM que matava o WebView.
206	    // O File reduzido (lado ≤2000px, JPEG 0.85) cabe em ~200KB–1MB e
207	    // remove a foto crua do alcance do GC sem cópias intermediárias.
208	    const downscaled = await downscaleIfImage(raw);
209	
210	    if (multiple && onFilesSelect) {
211	      // Multi-mode não persiste em localStorage (restore não suporta multi).
212	      const merged = [...selectedFiles, downscaled].slice(0, 2);
213	      onFilesSelect(merged);
214	      toast.success(`Foto ${merged.length} capturada com sucesso!`);
215	    } else {
216	      onFileSelect(downscaled);
217	      toast.success("Foto capturada com sucesso!");
218	      // Defesa em profundidade: persiste a foto reduzida em localStorage pra
219	      // permitir restore caso o Android mate o WebView antes do upload.
220	      // Falha aqui é silenciosa por design (a foto já está em memória).
221	      void savePendingCapture(downscaled);
222	    }
223	
224	    e.target.value = '';
225	  };
226	
227	  return (
228	    <div
229	      className={cn(
230	        'relative border-2 border-dashed rounded-lg p-4 sm:p-8 text-center transition-all duration-300 cursor-pointer',
231	        'hover:border-primary/50 hover:bg-primary/5',
232	        {
233	          'border-primary bg-primary/10 shadow-lg scale-[1.02]': isDragOver,
234	          'border-company-light': !isDragOver && !selectedFile && selectedFiles.length === 0,
235	          'border-green-400 bg-green-50': (selectedFile || selectedFiles.length > 0) && !isDragOver,
236	          'opacity-50 cursor-not-allowed': disabled,
237	          'transform hover:scale-[1.01]': !disabled && isHovering,
238	        },
239	      )}
240	      onDragEnter={handleDragEnter}
241	      onDragLeave={handleDragLeave}
242	      onDragOver={handleDragOver}
243	      onDrop={handleDrop}
244	      onClick={handleClick}
245	      onMouseEnter={() => setIsHovering(true)}
246	      onMouseLeave={() => setIsHovering(false)}
247	    >
248	      {/* Efeito de brilho quando em drag over */}
249	      {isDragOver && (
250	        <div
251	          className="absolute inset-0 bg-gradient-to-r from-blue-400/20 via-purple-400/20 to-blue-400/20 rounded-lg"
252	          style={{ animation: 'pulse 3s ease-in-out infinite' }}
253	        />
254	      )}
255	
256	      {/* Círculos animados quando em drag over */}
257	      {isDragOver && (
258	        <>
259	          <div
260	            className="absolute top-4 left-4 w-3 h-3 bg-primary/40 rounded-full"
261	            style={{
262	              animation: 'bounce 2s ease-in-out infinite',
263	              animationDelay: '0s',
264	            }}
265	          />
266	          <div
267	            className="absolute top-4 right-4 w-3 h-3 bg-primary/40 rounded-full"
268	            style={{
269	              animation: 'bounce 2s ease-in-out infinite',
270	              animationDelay: '0.5s',
271	            }}
272	          />
273	          <div
274	            className="absolute bottom-4 left-4 w-3 h-3 bg-primary/40 rounded-full"
275	            style={{
276	              animation: 'bounce 2s ease-in-out infinite',
277	              animationDelay: '1s',
278	            }}
279	          />
280	          <div
281	            className="absolute bottom-4 right-4 w-3 h-3 bg-primary/40 rounded-full"
282	            style={{
283	              animation: 'bounce 2s ease-in-out infinite',
284	              animationDelay: '1.5s',
285	            }}
286	          />
287	        </>
288	      )}
289	
290	      <div className="relative z-10">
291	        {/* Multi-file mode: show list of selected files */}
292	        {multiple && selectedFiles.length > 0 ? (
293	          <div className="space-y-3 sm:space-y-4">
294	            <div className="flex items-center justify-center">
295	              <div className="w-12 h-12 sm:w-16 sm:h-16 bg-green-100 rounded-full flex items-center justify-center">
296	                <CheckCircle className="w-6 h-6 sm:w-8 sm:h-8 text-green-600" />
297	              </div>
298	            </div>
299	            <div className="space-y-2">
300	              <p className="text-base sm:text-lg font-semibold text-green-700">
301	                {selectedFiles.length === 1 ? '1 página selecionada' : `${selectedFiles.length} páginas selecionadas`}
302	              </p>
303	              {selectedFiles.map((f, idx) => (
304	                <div key={idx} className="flex items-center justify-center gap-2 text-sm text-green-600">
305	                  <FileText className="h-3.5 w-3.5 flex-shrink-0" />
306	                  <span className="font-medium truncate max-w-[200px]">Pág. {idx + 1}: {f.name}</span>
307	                  <span className="text-xs text-muted-foreground">({(f.size / 1024 / 1024).toFixed(2)} MB)</span>
308	                  <button
309	                    type="button"
310	                    className="p-0.5 rounded-full hover:bg-red-100 text-red-400 hover:text-red-600 transition-colors"
311	                    onClick={(e) => {
312	                      e.stopPropagation();
313	                      const updated = selectedFiles.filter((_, i) => i !== idx);
314	                      onFilesSelect?.(updated);
315	                    }}
316	                  >
317	                    <X className="h-3.5 w-3.5" />
318	                  </button>
319	                </div>
320	              ))}
321	              {selectedFiles.length < 2 && (
322	                <div className="pt-2 flex items-center justify-center gap-2">
323	                  <Button
324	                    type="button"
325	                    variant="outline"
326	                    size="sm"
327	                    onClick={(e) => {
328	                      e.stopPropagation();
329	                      fileInputRef.current?.click();
330	                    }}
331	                    disabled={disabled}
332	                    className="gap-2 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/10 font-medium h-9 px-3 text-sm rounded-full"
333	                  >
334	                    <Plus className="h-4 w-4" />
335	                    Adicionar 2ª página
336	                  </Button>
337	                  {isMobile && hasCamera && !isChecking && (
338	                    <Button data-mia-action="camera-click"
339	                      type="button"
340	                      variant="outline"
341	                      size="sm"
342	                      onClick={handleCameraClick}
343	                      disabled={disabled}
344	                      className="gap-2 bg-primary/10 border-primary/30 hover:bg-primary/20 text-primary font-medium h-9 px-3 text-sm rounded-full"
345	                    >
346	                      <Camera className="h-4 w-4" />
347	                      Tirar 2ª foto
348	                    </Button>
349	                  )}
350	                </div>
351	              )}
352	            </div>
353	          </div>
