30	/**
31	 * Converts a Brazilian date (DD/MM/YYYY) to ISO format (YYYY-MM-DD).
32	 * Also handles dates the AI may have already converted to YYYY-MM-DD (validates & fixes swaps).
33	 * Returns null if the date cannot be parsed.
34	 */
35	function convertBrazilianDateToISO(dateStr: string | null | undefined): string | null {
36	  if (!dateStr || dateStr === 'null') return null;
37	  const cleaned = dateStr.trim();
38	
39	  // Case 1: DD/MM/YYYY or DD-MM-YYYY (Brazilian format — most reliable)
40	  const brMatch = cleaned.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
41	  if (brMatch) {
42	    const day = brMatch[1].padStart(2, '0');
43	    const month = brMatch[2].padStart(2, '0');
44	    const year = brMatch[3];
45	    const m = parseInt(month);
46	    const d = parseInt(day);
47	    if (m >= 1 && m <= 12 && d >= 1 && d <= 31) {
48	      return `${year}-${month}-${day}`;
49	    }
50	    if (m > 12 && d >= 1 && d <= 12) {
51	      return `${year}-${day.padStart(2, '0')}-${month}`;
52	    }
53	    return `${year}-${month}-${day}`;
54	  }
55	
56	  // Case 2: YYYY-MM-DD (AI already converted — validate and fix if swapped)
57	  const isoMatch = cleaned.match(/^(\d{4})-(\d{2})-(\d{2})$/);
58	  if (isoMatch) {
59	    const year = isoMatch[1];
60	    const part1 = isoMatch[2];
61	    const part2 = isoMatch[3];
62	    const p1 = parseInt(part1);
63	    const p2 = parseInt(part2);
64	    if (p1 > 12 && p2 >= 1 && p2 <= 12) {
65	      console.log(`[DATE FIX] Swapped date detected: ${cleaned} → ${year}-${part2}-${part1}`);
66	      return `${year}-${part2}-${part1}`;
67	    }
68	    return cleaned;
69	  }
70	
71	  console.warn(`[DATE WARN] Could not parse date: ${dateStr}`);
72	  return cleaned;
73	}
