163	/**
164	 * Extrai o primeiro objeto JSON balanceado de um texto.
165	 * Ignora chaves dentro de strings (respeita escapes). Retorna null se não encontrar.
166	 */
167	function extractBalancedJson(text: string): string | null {
168	  if (!text) return null;
169	  let start = -1;
170	  let depth = 0;
171	  let inString = false;
172	  let escape = false;
173	  for (let i = 0; i < text.length; i++) {
174	    const ch = text[i];
175	    if (escape) { escape = false; continue; }
176	    if (ch === '\\') { escape = true; continue; }
177	    if (ch === '"') { inString = !inString; continue; }
178	    if (inString) continue;
179	    if (ch === '{') {
180	      if (depth === 0) start = i;
181	      depth++;
182	    } else if (ch === '}') {
183	      depth--;
184	      if (depth === 0 && start !== -1) {
185	        return text.slice(start, i + 1);
186	      }
187	    }
188	  }
189	  return null;
190	}
