192	function tryParseAiJson(aiResponse: string): any {
193	  if (!aiResponse) return null;
194	  let cleaned = aiResponse.trim();
195	  if (cleaned.startsWith('```json')) {
196	    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```\s*$/, '');
197	  } else if (cleaned.startsWith('```')) {
198	    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```\s*$/, '');
199	  }
200	  const balanced = extractBalancedJson(cleaned) ?? cleaned;
201	  const sanitized = balanced
202	    .replace(/,\s*,/g, ',')
203	    .replace(/,\s*}/g, '}')
204	    .replace(/,\s*]/g, ']');
205	  try {
206	    return JSON.parse(sanitized);
207	  } catch {
208	    return null;
209	  }
210	}
