222	async function callOcrModel(
223	  model: string,
224	  apiKey: string,
225	  imageBase64: string,
226	  prompt: string,
227	): Promise<{ ok: true; data: any; usage: any; content: string } | { ok: false; reason: string }> {
228	  try {
229	    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
230	      method: 'POST',
231	      headers: {
232	        'Authorization': `Bearer ${apiKey}`,
233	        'Content-Type': 'application/json',
234	      },
235	      body: JSON.stringify({
236	        model,
237	        messages: [
238	          {
239	            role: 'user',
240	            content: [
241	              { type: 'text', text: prompt },
242	              { type: 'image_url', image_url: { url: `data:image/jpeg;base64,${imageBase64}` } },
243	            ],
244	          },
245	        ],
246	        temperature: 0.1,
247	      }),
248	    });
249	    if (!response.ok) {
250	      const errorText = await response.text();
251	      console.error(`[OCR] ${model} HTTP ${response.status}:`, errorText.slice(0, 300));
252	      return { ok: false, reason: `http_${response.status}` };
253	    }
254	    const data = await response.json();
255	    const content = data?.choices?.[0]?.message?.content ?? '';
256	    const parsed = tryParseAiJson(content);
257	    if (!parsed || typeof parsed !== 'object') {
258	      console.error(`[OCR] ${model} returned unparseable content:`, content.slice(0, 500));
259	      return { ok: false, reason: 'unparseable_json' };
260	    }
261	    if (!hasUsefulContent(parsed)) {
262	      console.error(`[OCR] ${model} returned empty object (no useful fields):`, JSON.stringify(parsed).slice(0, 500));
263	      return { ok: false, reason: 'empty_result' };
264	    }
265	    return { ok: true, data: parsed, usage: data.usage, content };
266	  } catch (e) {
267	    console.error(`[OCR] ${model} threw:`, (e as Error).message);
268	    return { ok: false, reason: 'exception' };
269	  }
270	}
