272	function normalizeCategoria(raw: unknown): string {
273	  if (!raw || typeof raw !== 'string') return 'Outros';
274	  const key = raw.trim().toLowerCase();
275	  if (!key) return 'Outros';
276	
277	  const direct = CATEGORIA_ALIASES[key];
278	  if (direct) return direct;
279	
280	  for (const canonica of CATEGORIAS_NF) {
281	    if (key === canonica.toLowerCase()) return canonica;
282	  }
283	  for (const [alias, canonica] of Object.entries(CATEGORIA_ALIASES)) {
284	    if (key.includes(alias)) return canonica;
285	  }
286	  return 'Outros';
287	}
