10	/**
11	 * Converts a Brazilian date (DD/MM/YYYY) to ISO format (YYYY-MM-DD).
12	 * Also handles dates the AI may have already converted to YYYY-MM-DD (validates & fixes swaps).
13	 * Returns null if the date cannot be parsed.
14	 */
15	function convertBrazilianDateToISO(dateStr: string | null | undefined): string | null {
16	  if (!dateStr || dateStr === 'null') return null;
17	  const cleaned = dateStr.trim();
18	
19	  // Case 1: DD/MM/YYYY or DD-MM-YYYY (Brazilian format — most reliable)
20	  const brMatch = cleaned.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
21	  if (brMatch) {
22	    const day = brMatch[1].padStart(2, '0');
23	    const month = brMatch[2].padStart(2, '0');
24	    const year = brMatch[3];
25	    // Validate: month must be 1-12, day must be 1-31
26	    const m = parseInt(month);
27	    const d = parseInt(day);
28	    if (m >= 1 && m <= 12 && d >= 1 && d <= 31) {
29	      return `${year}-${month}-${day}`;
30	    }
31	    // If month > 12 but day <= 12, AI may have swapped them — fix it
32	    if (m > 12 && d >= 1 && d <= 12) {
33	      return `${year}-${day.padStart(2, '0')}-${month}`;
34	    }
35	    return `${year}-${month}-${day}`;
36	  }
37	
38	  // Case 2: YYYY-MM-DD (AI already converted — validate and fix if swapped)
39	  const isoMatch = cleaned.match(/^(\d{4})-(\d{2})-(\d{2})$/);
40	  if (isoMatch) {
41	    const year = isoMatch[1];
42	    const part1 = isoMatch[2]; // should be month
43	    const part2 = isoMatch[3]; // should be day
44	    const p1 = parseInt(part1);
45	    const p2 = parseInt(part2);
46	    // If part1 (month) > 12, it's definitely swapped — fix it
47	    if (p1 > 12 && p2 >= 1 && p2 <= 12) {
48	      console.log(`[DATE FIX] Swapped date detected: ${cleaned} → ${year}-${part2}-${part1}`);
49	      return `${year}-${part2}-${part1}`;
50	    }
51	    return cleaned;
52	  }
53	
54	  console.warn(`[DATE WARN] Could not parse date: ${dateStr}`);
55	  return cleaned;
56	}
