1	// Persistência durável da foto capturada em Notas Fiscais para sobreviver ao
2	// kill do WebView pelo Android (PWA via Vercel).
3	//
4	// PORQUÊ não sessionStorage: o WebView é morto pelo Android quando a câmera
5	// nativa fica em foreground; ao retornar, o processo é recriado e
6	// `sessionStorage` é apagado (é per-session). `localStorage` é persistido em
7	// disco pelo WebView e sobrevive ao kill.
8	//
9	// PORQUÊ não IndexedDB: o JPEG já reduzido (lado <=2000px, qualidade 0.85) cabe
10	// em ~200KB–1.1MB em base64, folgado dentro da quota típica de 5MB do
11	// localStorage. Não vale o custo de polyfill em testes nem a complexidade
12	// async pra um caso de uma foto por sessão.
13	
14	const KEY_PHOTO = 'nf-pending-capture-v1';
15	const KEY_FLAG = 'nf-pending-capture-flag-v1';
16	
17	/** TTL da captura pendente. Após 10 min é considerada irrecuperável. */
18	const PHOTO_TTL_MS = 10 * 60 * 1000;
19	/** TTL do flag "abri a câmera mas não voltei ainda" — curto e só serve pra
20	 * reabrir o modal de upload caso o usuário tenha cancelado a câmera. */
21	const FLAG_TTL_MS = 60 * 1000;
22	
23	interface StoredPhoto {
24	  dataUrl: string;
25	  name: string;
26	  mime: string;
27	  ts: number;
28	}
29	
30	/**
31	 * Acesso defensivo ao localStorage — alguns contextos (modo privado raro,
32	 * iframes sandboxed) podem lançar SecurityError no simples acesso ao objeto.
33	 */
34	function getStorage(): Storage | null {
35	  try {
36	    if (typeof window === 'undefined') return null;
37	    return window.localStorage;
38	  } catch {
39	    return null;
40	  }
41	}
42	
43	function readJson<T>(key: string): T | null {
44	  const storage = getStorage();
45	  if (!storage) return null;
46	  try {
47	    const raw = storage.getItem(key);
48	    if (!raw) return null;
49	    return JSON.parse(raw) as T;
50	  } catch {
51	    // JSON corrompido — apaga pra não envenenar futuras leituras.
52	    try {
53	      storage.removeItem(key);
54	    } catch {
55	      /* noop */
56	    }
57	    return null;
58	  }
59	}
60	
61	function dataUrlToFile(dataUrl: string, name: string, mime: string): File | null {
62	  try {
63	    const commaIdx = dataUrl.indexOf(',');
64	    if (commaIdx < 0) return null;
65	    const payload = dataUrl.slice(commaIdx + 1);
66	    const binary = atob(payload);
67	    const bytes = new Uint8Array(binary.length);
68	    for (let i = 0; i < binary.length; i++) {
69	      bytes[i] = binary.charCodeAt(i);
70	    }
71	    return new File([bytes], name, { type: mime || 'image/jpeg' });
72	  } catch {
73	    return null;
74	  }
75	}
76	
77	function fileToDataUrl(file: File): Promise<string> {
78	  return new Promise((resolve, reject) => {
79	    const reader = new FileReader();
80	    reader.onload = () => resolve(String(reader.result || ''));
81	    reader.onerror = () => reject(reader.error ?? new Error('FileReader falhou'));
82	    reader.readAsDataURL(file);
83	  });
84	}
85	
86	/**
87	 * Persiste a foto reduzida + metadados em localStorage com timestamp.
88	 *
89	 * Erros (quota excedida, FileReader, indisponibilidade do storage) são
90	 * silenciados porque essa persistência é defesa em profundidade — o fluxo
91	 * principal já tem o File em memória; só não há recuperação se o WebView
92	 * morrer.
93	 */
94	export async function savePendingCapture(file: File): Promise<void> {
95	  const storage = getStorage();
96	  if (!storage) return;
97	  try {
98	    const dataUrl = await fileToDataUrl(file);
99	    const payload: StoredPhoto = {
100	      dataUrl,
101	      name: file.name || 'foto.jpg',
102	      mime: file.type || 'image/jpeg',
103	      ts: Date.now(),
104	    };
105	    storage.setItem(KEY_PHOTO, JSON.stringify(payload));
106	  } catch {
107	    // QuotaExceededError ou afins — limpa nossa chave pra liberar espaço
108	    // pra próxima tentativa e segue silencioso.
109	    try {
110	      storage.removeItem(KEY_PHOTO);
111	    } catch {
112	      /* noop */
113	    }
114	  }
115	}
116	
117	/** Marca que iniciamos uma captura (antes do click no input nativo). */
118	export function setPendingCaptureFlag(): void {
119	  const storage = getStorage();
120	  if (!storage) return;
121	  try {
122	    storage.setItem(KEY_FLAG, String(Date.now()));
123	  } catch {
124	    /* noop */
125	  }
126	}
127	
128	/** Apaga só o flag de captura iniciada. */
129	export function clearPendingCaptureFlag(): void {
130	  const storage = getStorage();
131	  if (!storage) return;
132	  try {
133	    storage.removeItem(KEY_FLAG);
134	  } catch {
135	    /* noop */
136	  }
137	}
138	
139	/**
140	 * Lê a captura pendente. Retorna `null` quando:
141	 * - não há nada armazenado;
142	 * - o TTL expirou (maior que 10 min) — nesse caso a entrada é apagada;
143	 * - o payload está corrompido ou o storage não está disponível.
144	 */
145	export function loadPendingCapture(): { file: File; ts: number } | null {
146	  const storage = getStorage();
147	  if (!storage) return null;
148	  const stored = readJson<StoredPhoto>(KEY_PHOTO);
149	  if (!stored || !stored.dataUrl || !stored.ts) return null;
150	  if (Date.now() - stored.ts > PHOTO_TTL_MS) {
151	    try {
152	      storage.removeItem(KEY_PHOTO);
153	    } catch {
154	      /* noop */
155	    }
156	    return null;
157	  }
158	  const file = dataUrlToFile(stored.dataUrl, stored.name, stored.mime);
159	  if (!file) return null;
160	  return { file, ts: stored.ts };
161	}
162	
163	/** Remove a captura pendente e qualquer flag em uso. */
164	export function clearPendingCapture(): void {
165	  const storage = getStorage();
166	  if (!storage) return;
167	  try {
168	    storage.removeItem(KEY_PHOTO);
169	    storage.removeItem(KEY_FLAG);
170	  } catch {
171	    /* noop */
172	  }
173	}
174	
175	/**
176	 * Resposta rápida pro hook de boot: existe captura pendente recente OU flag
177	 * recente "abri a câmera"? Usado pra decidir se redireciona o usuário pra
178	 * `/notas-fiscais` quando o app boota após um kill do WebView.
179	 */
180	export function hasRecentPendingCapture(): boolean {
181	  const storage = getStorage();
182	  if (!storage) return false;
183	  const now = Date.now();
184	
185	  const stored = readJson<StoredPhoto>(KEY_PHOTO);
186	  if (stored?.ts && now - stored.ts <= PHOTO_TTL_MS) return true;
187	
188	  try {
189	    const flagRaw = storage.getItem(KEY_FLAG);
190	    if (flagRaw) {
191	      const flagTs = Number(flagRaw);
192	      if (Number.isFinite(flagTs) && now - flagTs <= FLAG_TTL_MS) return true;
193	    }
194	  } catch {
195	    /* noop */
196	  }
197	  return false;
198	}
199	
200	// Re-export das constantes pra facilitar testes e ajuste futuro.
201	export const NF_PENDING_CAPTURE_KEYS = { KEY_PHOTO, KEY_FLAG };
202	export const NF_PENDING_CAPTURE_TTLS = { PHOTO_TTL_MS, FLAG_TTL_MS };
