function hasUsefulContent(parsed: any): boolean {
  if (!parsed || typeof parsed !== 'object') return false;
  const hasNumero = typeof parsed.numero_nota === 'string' && parsed.numero_nota.trim().length > 0;
  const hasFornecedor = typeof parsed.fornecedor === 'string' && parsed.fornecedor.trim().length > 0;
  const hasValor = typeof parsed.valor_total === 'number' && parsed.valor_total > 0;
  const hasItens = Array.isArray(parsed.itens) && parsed.itens.length > 0;
  const hasData = typeof parsed.data_nota === 'string' && parsed.data_nota.trim().length > 0;
  return hasNumero || hasFornecedor || hasValor || hasItens || hasData;
}
```

